local RunService = game:GetService("RunService")

local function ui(debugger, loop)
	local plasma = debugger.Plasma
	local custom = debugger._customWidgets
    local timer = debugger.WKTimer

	plasma.setStyle({
		primaryColor = Color3.fromHex("bd515c"),
		guiInset = 60,
		panelHeight = debugger._plasmaNode.instance.AbsoluteSize.Y - 180,
	})

	local objectStack = debugger.ObjectStack
	local operations = debugger.Operations
	local clickedType, setClickedType = plasma.useState("")
	local timeViewOpen, setTimeViewOpen = plasma.useState(false)
	local propsViewOpen, setPropsViewOpen = plasma.useState(false)
	local userViewOpen, setUserViewOpen = plasma.useState(false)
	local cheatType, setCheatType = plasma.useState("")

	custom.container(function()
		if custom.panel(function()
			plasma.space(10)
			local filter
			if debugger._isAdmin then
				if custom.timeButton(timer.GetDateTime():ToString():gsub("%s", "\n"), {
					isOpened = timeViewOpen
				}):clicked() then
					setTimeViewOpen(not timeViewOpen)
				end

				plasma.space(10)
				filter = custom.textBox1("filter...").Text()
				filter = string.gsub(filter, "%s+", "")

				plasma.space(10)
				plasma.heading("SYSTEMS")
				plasma.space(10)
				local items = {
					{
						text = "玩家容器",
						selected = false,
					},
					{
						text = "计算属性",
						selected = false,
					},
				}

				items[1].selected = (#objectStack > 0 and objectStack[1].value == debugger.Root)
				items[2].selected = propsViewOpen

				local selectedState = custom.selectionList(items):selected()
				if selectedState then
					if selectedState.text == "玩家容器" then
						setClickedType("")
						setCheatType()

						if #objectStack == 0 or (#objectStack > 0 and objectStack[1].value ~= debugger.Root) then
							table.clear(objectStack)
							objectStack[1] = {
								key = selectedState.text,
								icon = selectedState.icon,
								value = debugger.Root
							}
						else
							table.clear(objectStack)
						end
					elseif selectedState.text == "计算属性" then
						setPropsViewOpen(not propsViewOpen)
						setCheatType()

						local props = debugger.PlayerProps or {}
						if not next(props) then
							for i, v in pairs(debugger.Root:GetChildren()) do
								if v._type2 == "ElementContainer" and v._item.ElementType == 1 then
									local groupId = v:GetId()
									if not props[groupId] then
										props[groupId] = {}
									end
									for j, k in pairs(v:GetSortedChildren()) do
										table.insert(props[groupId], k)
									end
								end
							end
						end
						debugger.PlayerProps = props
					end
				end
				plasma.space(30)
				-- todo 读取收藏配置
				if #debugger.Favorites > 0 then
					plasma.heading("FAVORITES")
					plasma.space(10)
					local items = {}
					for i, v in pairs(debugger.Favorites) do
						local id = v:GetId()
						if string.find(id, filter) then
							table.insert(items, {
								text = v:GetId(),
								selected = false,
								object = v
							})
						end
					end

					for i, v in pairs(items) do
						local object = v.object
						local selected = clickedType == "FAVORITES" and (#objectStack > 0 and object == objectStack[1].value)
						v.selected = selected
					end

					local selectedState = custom.selectionList(items):selected()
					if selectedState then
						table.clear(operations)
						if clickedType == "FAVORITES" and #objectStack > 0 and selectedState.object == objectStack[1].value then
							table.clear(objectStack)
						else
							table.clear(objectStack)
							objectStack[1] = {	
								key = selectedState.text,
								icon = selectedState.icon,
								value = selectedState.object
							}
						end
						setClickedType("FAVORITES")
						setCheatType()
					end
					plasma.space(30)
				end
			end

			if #debugger._funcs and next(debugger._funcs) then
				
				local items = {}
				local modItems = {}

				for i, v in pairs(debugger._funcs) do
					if i ~= "Self" then
						if v[1] and v[1].type ~= "Mod" then
							table.insert(items, {
								text = i,
								selected = false,
								funcs = v
							})
						else
							table.insert(modItems, {
								text = i,
								selected = false,
								funcs = v
							})
						end
					end
				end

				
				table.sort(items, function(a, b)
					return a.text < b.text
				end)

				table.sort(modItems, function(a, b)
					return a.text < b.text
				end)
				
				if debugger._funcs["Self"] then
					table.insert(items, 1, {
						text = "Self",
						selected = false,
						funcs = debugger._funcs["Self"]
					})
				end

				for i, v in pairs(items) do
					v.selected = cheatType == v.text
				end
				for i, v in pairs(modItems) do
					v.selected = cheatType == v.text
				end

				if #items > 0 then
					plasma.heading("ADMIN")
					plasma.space(10)
					local selectedState = custom.selectionList(items):selected()
					if selectedState then
						if selectedState.text ~= cheatType then
							setCheatType(selectedState.text)
							setUserViewOpen(false)
							setTimeViewOpen(false)
							setPropsViewOpen(false)
							table.clear(objectStack)
							debugger._cheating = nil
						else
							setCheatType()
							debugger._cheating = nil
						end
					end
					plasma.space(30)
				end

				if #modItems > 0 then
					plasma.heading("Mod")
					plasma.space(10)
					local selectedState = custom.selectionList(modItems):selected()
					if selectedState then
						if selectedState.text ~= cheatType then
							setCheatType(selectedState.text)
							setUserViewOpen(false)
							setTimeViewOpen(false)
							setPropsViewOpen(false)
							table.clear(objectStack)
							debugger._cheating = nil
						else
							setCheatType()
							debugger._cheating = nil
						end
					end
					plasma.space(30)
				end
			end

			if debugger._isAdmin then
				plasma.heading("CONTAINER")
				plasma.space(10)
				
				local items = {}
				for i, v in pairs(debugger.Root:GetChildren()) do
					local id = v:GetId()
					if string.find(id, filter) then
						table.insert(items, {
							text = v:GetId(),
							selected = false,
							object = v
						})
					end
				end

				for i, v in pairs(items) do
					local object = v.object
					local selected = clickedType == "CONTAINER" and (#objectStack > 0 and object == objectStack[1].value)
					v.selected = selected
				end

				local selectedState = custom.selectionList(items):selected()
				if selectedState then
					table.clear(operations)
					if clickedType == "CONTAINER" and #objectStack > 0 and selectedState.object == objectStack[1].value then
						table.clear(objectStack)
					else
						table.clear(objectStack)
						objectStack[1] = {	
							key = selectedState.text,
							icon = selectedState.icon,
							value = selectedState.object
						}
					end
					setClickedType("CONTAINER")
					setCheatType()
				end
				plasma.space(30)
			end
		end, debugger):clicked() then
			setUserViewOpen(true)
			setCheatType()
		end

		custom.container(function()
			if userViewOpen then
				if debugger._isClientDev then
					local closed = custom.userInspect(debugger)
					if closed then
						setUserViewOpen(false)
					end
				else
					warn("请在客户端调试下运行")
					setUserViewOpen(false)
				end
			end
			if timeViewOpen then
				local closed = custom.timeInspect(debugger)
				if closed then
					setTimeViewOpen(false)
				end
			end
			if propsViewOpen then
				local closed = custom.propsInspect(debugger)
				if closed then
					setPropsViewOpen(false)
				end
			end
			if #objectStack > 0 then
				local closed = custom.nodeInspect(debugger, objectStack, operations)
				if closed then
					table.clear(objectStack)
				end
				if #operations > 0 and #objectStack > 0 then
					local closed = custom.executeInspect(debugger, objectStack[#objectStack], operations[1])
					if closed then
						table.clear(operations)
					end
				else
					debugger.ExecuteRes = nil
				end
			else
				table.clear(operations)
			end

			if cheatType and cheatType ~= "" then
				local closed = custom.cheatInspect(debugger, cheatType)
				if closed then
					setCheatType()
				end
			else
				debugger._cheating = nil
				debugger._cheatRes = nil
			end

			if debugger._cheating then
				local closed = custom.cheatExecuteInspect(debugger)
				if closed then
					debugger._cheating = nil
					debugger._cheatRes = nil
				end
			end
		end, {
			marginTop = 60,
			marginLeft = 10,
			direction = Enum.FillDirection.Horizontal,
		})
		debugger.frame = custom
	end, {
		direction = Enum.FillDirection.Horizontal,
		padding = 0,
	})
end

return ui